describe('Navigation from Home Page to Example Page', () => {
    beforeEach(() => {
        cy.visit('https://the-internet.herokuapp.com');
    });

    it('should display the home page with the correct heading', () => {
        cy.contains('h1', 'Welcome to the-internet').should('be.visible');
    });

    it('should navigate to A/B Testing page and back to home page', () => {
        cy.contains('A/B Testing').click();
        cy.url().should('include', '/abtest');
        cy.contains('h3', 'A/B Test').should('be.visible');

        cy.go('back');
        cy.contains('h1', 'Available Examples').should('be.visible');
    });
});
